import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Your score out of 100? ");
        int score = scanner.nextInt();

        boolean passed = score >= 50;
        boolean perfect = score == 100;

        System.out.println("Passed:  " + passed);
        System.out.println("Perfect: " + perfect);
    }
}

public class Main {
    public static void main(String[] args) {
        String a = "yes";
        String b = "yes";                 // the same shared copy
        String c = new String("yes");     // deliberately a separate object

        System.out.println(a == b);        // true, but only by luck
        System.out.println(a == c);        // false, same letters
        System.out.println(a.equals(c));   // true: this is the right question
    }
}

